BLOCKS = [(0x20, 0x7F), (0xA0, 0x100), (0x370, 0x400), (0x2000, 0x2070), (0x2100, 0x2150), (0x2190, 0x2200),
          (0x2200, 0x2300), (0x2300, 0x2400)]


def _generate(fonts):
    from fontTools.ttLib import TTFont

    import symbol_fonts

    def latin(fn):
        f = TTFont(fonts / fn)
        em, hm, cm = f["head"].unitsPerEm, f["hmtx"].metrics, f.getBestCmap()
        return {chr(c): round(1000 * hm[cm[c]][0] / em) for a, b in BLOCKS for c in range(a, b) if c in cm}

    def symbol():
        f = TTFont(fonts / "symbol.ttf")
        em, hm = f["head"].unitsPerEm, f["hmtx"].metrics
        cm = next(t.cmap for t in f["cmap"].tables if t.platformID == 3 and t.platEncID == 0)
        out = {}
        for b, cp in sorted(symbol_fonts.table("Symbol").items()):
            g = cm.get(0xF000 + b)
            if g is not None:
                out.setdefault(chr(cp), round(1000 * hm[g][0] / em))
        return out

    return {"Times New Roman|0": latin("times.ttf"), "Times New Roman|1": latin("timesi.ttf"), "Symbol|0": symbol()}


if __name__ == "__main__":
    import sys
    from pathlib import Path

    got = _generate(Path(sys.argv[1]))
    have = {k: dict(zip(cs, ws)) for k, (cs, ws) in WIDTH.items()}
    print({k: (len(have[k]), len(got[k]), have[k] == got[k]) for k in WIDTH})
    sys.exit(0 if have == got else 1)
